// Template for the generated menu category pages.
//
// Imported by tools/build-menu-pages.mjs (to write the pages) and by
// site/menu-pages.test.js (to assert the committed pages still match the data).
// Both must import the same module, or the drift test proves nothing.

export const GENERATED_BANNER =
  '<!-- GENERATED by tools/build-menu-pages.mjs from menu-data.js. Do not edit by hand — run `npm run build:menu`. -->';

const SITE = 'https://vaavkitchenandcaterers.com';

/** "Dinner 5" -> "dinner-5". Menu names are test-guaranteed unique, so slugs cannot collide. */
export function slug(name) {
  return String(name).toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '');
}

/** Escape a value for HTML text or a double-quoted attribute. */
export function esc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

const titleCase = s => String(s).charAt(0).toUpperCase() + String(s).slice(1);

/**
 * Per-category head copy. Distinct titles and descriptions, drawn from the real
 * dish vocabulary in menu-data.js — never templated boilerplate, which would read
 * as duplicate content across three near-identical pages.
 */
export const CATEGORY_META = {
  tiffin: {
    h1: 'Tiffin set menus',
    title: 'Tiffin Catering Menu — 20 Pure Veg Tiffin Sets | VAAV Kitchen',
    description:
      'All 20 VAAV tiffin set menus with every dish listed — idli, dosai, ghee pongal, medhu vadai, poori and chutney spreads for seemanthams, housewarmings and office breakfasts in Chennai.',
    ogTitle: 'Tiffin Catering Menu — 20 Pure Veg Sets | VAAV Kitchen, Chennai',
    ogDescription:
      '20 tiffin set menus, every dish listed. Idli, dosai, pongal, vadai and chutney spreads for morning functions across Chennai.'
  },
  lunch: {
    h1: 'Lunch set menus',
    title: 'Lunch Catering Menu — 20 Pure Veg Sappadu Sets | VAAV Kitchen',
    description:
      'All 20 VAAV lunch set menus with every dish listed — the banana-leaf sappadu with rice, sambar, rasam, vatha kulambu, poriyal, appalam and payasam, for weddings and receptions in Chennai.',
    ogTitle: 'Lunch Catering Menu — 20 Pure Veg Sappadu Sets | VAAV Kitchen',
    ogDescription:
      '20 lunch set menus, every dish listed. The classic banana-leaf sappadu, from a simple plate to a full feast.'
  },
  dinner: {
    h1: 'Dinner set menus',
    title: 'Dinner Catering Menu — 26 Pure Veg Dinner Sets | VAAV Kitchen',
    description:
      'All 26 VAAV dinner set menus with every dish listed — sweets, starters, biryani, bisi bele bath, kuzhambu and a full main course for wedding receptions in Chennai.',
    ogTitle: 'Dinner Catering Menu — 26 Pure Veg Sets | VAAV Kitchen, Chennai',
    ogDescription:
      '26 dinner set menus, every dish listed. Grand evening spreads with sweets, starters, biryani and a full main course.'
  }
};

const ORDER = ['tiffin', 'lunch', 'dinner'];

/** Rebuild the head: keep the source chrome byte-for-byte, swap only the per-page meta. */
function buildHead(sourceHead, catKey, meta) {
  const url = `${SITE}/menu/${catKey}/`;
  let h = sourceHead
    // Drop the source page's JSON-LD; this page carries its own.
    .replace(/<script type="application\/ld\+json">[\s\S]*?<\/script>\s*/g, '')
    .replace(/<title>[\s\S]*?<\/title>/, `<title>${esc(meta.title)}</title>`)
    .replace(/<meta name="description" content="[^"]*">/, `<meta name="description" content="${esc(meta.description)}">`)
    .replace(/<link rel="canonical" href="[^"]*">/, `<link rel="canonical" href="${url}">`)
    .replace(/<meta property="og:url" content="[^"]*">/, `<meta property="og:url" content="${url}">`)
    .replace(/<meta property="og:title" content="[^"]*">/, `<meta property="og:title" content="${esc(meta.ogTitle)}">`)
    .replace(/<meta property="og:description" content="[^"]*">/, `<meta property="og:description" content="${esc(meta.ogDescription)}">`)
    .replace(/<meta name="twitter:title" content="[^"]*">/, `<meta name="twitter:title" content="${esc(meta.ogTitle)}">`)
    .replace(/<meta name="twitter:description" content="[^"]*">/, `<meta name="twitter:description" content="${esc(meta.ogDescription)}">`)
    .replace(/<link rel="prefetch"[^>]*>(<link rel="prefetch"[^>]*>)?/, '<link rel="prefetch" href="/menu/"><link rel="prefetch" href="/contact/">');
  return h.trimEnd();
}

/** BreadcrumbList + Menu JSON-LD for one category page. */
function buildSchema(catKey, data) {
  const url = `${SITE}/menu/${catKey}/`;
  const breadcrumb = {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: [
      { '@type': 'ListItem', position: 1, name: 'Home', item: `${SITE}/` },
      { '@type': 'ListItem', position: 2, name: 'Menu & Packages', item: `${SITE}/menu/` },
      { '@type': 'ListItem', position: 3, name: `${data.label} set menus`, item: url }
    ]
  };
  const menu = {
    '@context': 'https://schema.org',
    '@type': 'Menu',
    name: `VAAV Kitchen and Caterers — ${data.label} Set Menus`,
    inLanguage: 'en',
    url,
    provider: {
      '@type': 'FoodEstablishment',
      '@id': `${SITE}/#business`,
      name: 'VAAV Kitchen and Caterers'
    },
    hasMenuSection: [
      {
        '@type': 'MenuSection',
        name: data.label,
        url,
        hasMenuItem: data.menus.map(m => ({
          '@type': 'MenuItem',
          name: m.name,
          url: `${url}#${slug(m.name)}`
        }))
      }
    ]
  };
  return [breadcrumb, menu]
    .map(o => `<script type="application/ld+json">\n${JSON.stringify(o, null, 2)}\n</script>`)
    .join('\n');
}

/** One <article> per set menu, with an id so /menu/dinner/#dinner-5 deep-links to it. */
function renderSet(m) {
  const occ = (m.occasions || []).map(o => esc(titleCase(o))).join(', ');
  const total = (m.groups || []).reduce((n, g) => n + (g[1] ? g[1].length : 0), 0);
  const parts = [];
  parts.push(`      <article class="set" id="${slug(m.name)}">`);
  parts.push(`        <h2>${esc(m.name)}</h2>`);
  parts.push(`        <p class="set-occ">${total} dishes${occ ? ` · Suited to: ${occ}` : ''}</p>`);
  for (const [label, items] of m.groups || []) {
    // Tiffin and lunch sets carry a single group literally labelled "Items";
    // printing that as a heading on 40 of 66 sets would be noise.
    const single = (m.groups || []).length === 1 && label === 'Items';
    if (!single) parts.push(`        <h3>${esc(label)}</h3>`);
    parts.push('        <ul class="set-dishes">');
    for (const dish of items || []) parts.push(`          <li>${esc(dish)}</li>`);
    parts.push('        </ul>');
  }
  parts.push('      </article>');
  return parts.join('\n');
}

/**
 * Render one complete category page.
 * `chrome` is { head, top, bottom } extracted verbatim from site/menu/index.html,
 * so the CSP, nav, footer and scripts can never drift from the rest of the site.
 */
export function renderCategoryPage(catKey, data, chrome) {
  const meta = CATEGORY_META[catKey];
  if (!meta) throw new Error(`no CATEGORY_META for "${catKey}"`);
  const others = ORDER.filter(c => c !== catKey);
  const waHref =
    "https://wa.me/919655356333?text=Hello%20VAAV%20Kitchen%2C%20I'd%20like%20to%20enquire%20about%20" +
    encodeURIComponent(`${data.label.toLowerCase()} catering`) + '.';

  const main = [
    '<main id="main">',
    '  <section class="wrap sec">',
    `    <nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a> <span aria-hidden="true">/</span> <a href="/menu/">Menu &amp; Packages</a> <span aria-hidden="true">/</span> <span aria-current="page">${esc(data.label)}</span></nav>`,
    '    <div class="sec-head">',
    `      <p class="eyebrow">${esc(data.label)} &middot; ${esc(data.tamil)}</p>`,
    `      <h1>${esc(meta.h1)}</h1>`,
    `    </div>`,
    // data.note is authored HTML containing <strong>; it is the one value inserted raw.
    `    <p class="menu-intro">${data.note}</p>`,
    `    <p class="set-count"><b>${data.menus.length}</b> sets &middot; every dish listed below &middot; all customisable, including Jain and no onion-garlic.</p>`,
    '    <div class="set-list">',
    data.menus.map(renderSet).join('\n'),
    '    </div>',
    '    <p class="set-more">Mix and match across any set — we tailor the spread to your event. <a href="/menu/">Browse the menus one at a time</a>, or see every ' +
      others.map(c => `<a href="/menu/${c}/">${esc(CATEGORY_META[c].h1.replace(' set menus', ''))} set</a>`).join(' and every ') +
      '.</p>',
    `    <p class="set-cta"><a class="btn" data-wa-context="${esc(data.label.toLowerCase())} catering" href="${waHref}" target="_blank" rel="noopener noreferrer">Ask for a ${esc(data.label.toLowerCase())} quote on WhatsApp</a></p>`,
    '  </section>',
    '</main>'
  ].join('\n');

  // Drop the dataset: only the /menu/ explorer reads window.VAAV_MENUS, and it
  // bails on any page without #catTabs. This page has none, and every dish is
  // already here as static HTML, so menu-data.js would be 21 KB fetched and
  // parsed for nothing. /script.js stays — it still drives the nav toggle, the
  // WhatsApp links, the year stamp and the shortlist pill here.
  const bottom = chrome.bottom.replace(/<script src="\/menu-data\.js"[^>]*><\/script>\n?/, '');

  const html = [
    GENERATED_BANNER,
    '<!DOCTYPE html>',
    '<html lang="en">',
    '<head>',
    buildHead(chrome.head, catKey, meta),
    buildSchema(catKey, data),
    '</head>',
    chrome.top,
    main,
    bottom
  ].join('\n') + '\n';

  // Guard the replace above. It matches the tag as menu/index.html writes it
  // today; reformat that tag and the strip silently stops firing, putting 21 KB
  // back on all three pages with nothing to notice. Break the build instead.
  // Checked on the output, not the source chrome, because /menu/ itself is
  // entitled to the tag — and this runs for the drift test too, not just the
  // generator, since both call renderCategoryPage.
  if (/<script[^>]+menu-data\.js/.test(html)) {
    throw new Error(`the ${catKey} page still ships menu-data.js — the strip in renderCategoryPage no longer matches the tag in menu/index.html`);
  }
  return html;
}
